#include <omp.h>
#include <vector>
#include <string>
#include <cstddef>

struct Book {
   std::string title;
   int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
   const size_t n = books.size();
   if (n == 0) return static_cast<size_t>(-1);

   // Use a signed type for reduction with max; initialize to "not found"
   long long best = -1;

   #pragma omp parallel for reduction(max:best)
   for (long long i = 0; i < static_cast<long long>(n); ++i) {
      if (books[static_cast<size_t>(i)].pages < 100) {
         if (i > best) best = i; // thread-local due to reduction
      }
   }

   return (best < 0) ? static_cast<size_t>(-1) : static_cast<size_t>(best);
}
